function s(v) { return String(v == null ? '' : v).trim(); }
function colLetter(i) { let n = i + 1, out = ''; while (n > 0) { const m = (n - 1) % 26; out = String.fromCharCode(65 + m) + out; n = Math.floor((n - 1) / 26); } return out; }
const inv = $('GET INVESTORS').first().json.values || [];
const pipe = $('GET PIPELINE').first().json.values || [];
if (inv.length < 200) { throw new Error('ABORT: INVESTORS only ' + inv.length); }
if (pipe.length < 500) { throw new Error('ABORT: PIPELINE only ' + pipe.length); }
const TODAY = '2026-09-15';
const updates = [];

// ---- 1. Hem Angels: drop Tanul Goyal, keep Aditya only ----
const ih = (inv[0] || []).map(s);
const iInv = ih.indexOf('investor'), iCon = ih.indexOf('contact_person'), iEm = ih.indexOf('email'), iCc = ih.indexOf('cc');
if (iInv < 0 || iCon < 0 || iEm < 0 || iCc < 0) { throw new Error('ABORT: INVESTORS missing a needed column'); }
let hem = null;
for (let r = 1; r < inv.length; r++) { if (s((inv[r] || [])[iInv]) === 'Hem Angels') {
  if (hem) { throw new Error('ABORT: more than one Hem Angels row'); }
  hem = { row: r + 1, contact: s((inv[r] || [])[iCon]), email: s((inv[r] || [])[iEm]), cc: s((inv[r] || [])[iCc]) }; } }
if (!hem) { throw new Error('ABORT: Hem Angels row not found in INVESTORS'); }
function stripTanul(v) { return s(v).split(/[,;]+/).map(function (x) { return x.trim(); }).filter(function (x) { return x && !/tanul/i.test(x); }).join(', '); }
const hemChanges = [];
const newContact = 'Aditya';
if (hem.contact !== newContact) { updates.push({ range: 'INVESTORS!' + colLetter(iCon) + hem.row, values: [[newContact]] }); hemChanges.push(['contact_person', hem.contact, newContact]); }
const e2 = stripTanul(hem.email), c2 = stripTanul(hem.cc);
if (e2 !== hem.email) { updates.push({ range: 'INVESTORS!' + colLetter(iEm) + hem.row, values: [[e2]] }); hemChanges.push(['email', hem.email, e2]); }
if (c2 !== hem.cc) { updates.push({ range: 'INVESTORS!' + colLetter(iCc) + hem.row, values: [[c2]] }); hemChanges.push(['cc', hem.cc, c2]); }
if (!e2) { throw new Error('ABORT: stripping Tanul would leave Hem Angels with no email'); }

// ---- 2. VOLD Energy x Narotam Sekhsaria: founder already shared it inside the Bon Cuisine thread ----
const ph = (pipe[0] || []).map(s);
const P = {};
['startup','investor','email','deal_shared','date_shared','pause','next_action','next_due','last_contact','notes','deal_id','owner'].forEach(function (n) { P[n] = ph.indexOf(n); if (P[n] < 0) { throw new Error('ABORT: PIPELINE missing ' + n); } });
const hits = [];
for (let r = 1; r < pipe.length; r++) { const row = pipe[r] || [];
  if (!/vold/i.test(s(row[P.startup]))) { continue; }
  if (!/sekhsaria/i.test(s(row[P.investor]) + ' ' + s(row[P.email]))) { continue; }
  hits.push({ row: r + 1, deal_id: s(row[P.deal_id]), startup: s(row[P.startup]), investor: s(row[P.investor]), owner: s(row[P.owner]),
    email: s(row[P.email]), deal_shared: s(row[P.deal_shared]), pause: s(row[P.pause]), next_action: s(row[P.next_action]), next_due: s(row[P.next_due]), notes: s(row[P.notes]) }); }
if (hits.length !== 1) { throw new Error('ABORT: expected exactly 1 VOLD x Sekhsaria row, found ' + hits.length + ': ' + JSON.stringify(hits)); }
const v = hits[0];
const why = 'Shared manually by the founder inside the Bon Cuisine thread on ' + TODAY + ' - do not send, do not follow up; response tracked manually';
updates.push({ range: 'PIPELINE!' + colLetter(P.deal_shared) + v.row, values: [['Yes']] });
updates.push({ range: 'PIPELINE!' + colLetter(P.date_shared) + v.row, values: [[TODAY]] });
updates.push({ range: 'PIPELINE!' + colLetter(P.last_contact) + v.row, values: [[TODAY]] });
updates.push({ range: 'PIPELINE!' + colLetter(P.pause) + v.row, values: [['Yes']] });
updates.push({ range: 'PIPELINE!' + colLetter(P.next_action) + v.row, values: [['Manual - shared in Bon Cuisine thread, no follow-ups']] });
updates.push({ range: 'PIPELINE!' + colLetter(P.next_due) + v.row, values: [['']] });
updates.push({ range: 'PIPELINE!' + colLetter(P.notes) + v.row, values: [[(v.notes ? v.notes + ' | ' : '') + why]] });

return [{ json: { summary: { hem_row: hem.row, hem_changes: hemChanges.length, vold_row: v.row, vold_deal_id: v.deal_id, cell_writes: updates.length },
  hem_before: hem, hem_changes: hemChanges, vold_before: v, updates: updates } }];

function s(v) { return String(v == null ? '' : v).trim(); }
const plan = $('Plan').first().json;
const vr = $input.first().json.valueRanges || [];
const inv = (vr[0] || {}).values || [];
const pipe = (vr[1] || {}).values || [];
if (!inv.length || !pipe.length) { throw new Error('ABORT: verify read returned nothing'); }
const ih = (inv[0] || []).map(s);
const iInv = ih.indexOf('investor'), iCon = ih.indexOf('contact_person'), iEm = ih.indexOf('email'), iCc = ih.indexOf('cc');
let hemRow = null;
for (let r = 1; r < inv.length; r++) { if (s((inv[r] || [])[iInv]) === 'Hem Angels') { hemRow = inv[r]; } }
const hemContact = hemRow ? s(hemRow[iCon]) : '(missing)';
const hemEmail = hemRow ? s(hemRow[iEm]) : '';
const hemTanulLeft = hemRow ? /tanul/i.test(hemRow.join(' ')) : false;

const ph = (pipe[0] || []).map(s);
const P = {};
['startup','investor','deal_shared','date_shared','pause','next_action','next_due'].forEach(function (n) { P[n] = ph.indexOf(n); });
const v = pipe[plan.summary.vold_row - 1] || [];
const vold = { startup: s(v[P.startup]), investor: s(v[P.investor]), deal_shared: s(v[P.deal_shared]), date_shared: s(v[P.date_shared]), pause: s(v[P.pause]), next_action: s(v[P.next_action]), next_due: s(v[P.next_due]) };

// any other live VOLD row pointing at Sekhsaria?
let otherLive = 0;
for (let r = 1; r < pipe.length; r++) { const row = pipe[r] || [];
  if (!/vold/i.test(s(row[P.startup]))) { continue; }
  if (!/sekhsaria/i.test(s(row[P.investor]))) { continue; }
  if (s(row[P.pause]).toLowerCase() !== 'yes') { otherLive++; } }

const wrote = $('Write updates').first().json || {};
return [{ json: { cells_updated: wrote.totalUpdatedCells || 0,
  hem_contact_now: hemContact, hem_email_now: hemEmail, hem_tanul_still_present: hemTanulLeft,
  hem_changes_applied: plan.hem_changes,
  vold_now: vold, vold_deal_id: plan.summary.vold_deal_id, other_live_vold_sekhsaria_rows: otherLive,
  ok: hemContact === 'Aditya' && !hemTanulLeft && vold.deal_shared === 'Yes' && vold.pause === 'Yes' && vold.next_due === '' && otherLive === 0 } }];
